// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Still within the lock period: block has not advanced past lock block.
        uint256 lockedBlock = block.number + 1;
        vm.roll(lockedBlock);

        vm.prank(actor);
        bool ok; try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
